(()=>{const l={zh:{home:'首页',tools:'AI 工具',history:'历史',projects:'项目',account:'账户'},en:{home:'Home',tools:'AI Tools',history:'History',projects:'Projects',account:'Account'}},g=()=>document.documentElement.lang==='zh-CN'?'zh':'en',c=()=>{const p=new URLSearchParams(location.search);if(/create-(visual|writing|presentation|video)\.html$/.test(location.pathname))return 'tools';if(/account(?:\.html)?$/.test(location.pathname)){const v=p.get('view');return v==='chats'?'history':v==='projects'?'projects':'account'}return p.has('project')?'projects':p.has('conversation')?'history':location.hash==='#discover'?'tools':'home'},s=()=>{const a=c();document.querySelectorAll('.mobile-app-nav').forEach(n=>n.querySelectorAll('[data-mobile-destination]').forEach(x=>{const d=x.dataset.mobileDestination;x.textContent=l[g()][d];const v=d===a;x.classList.toggle('active',v),x.toggleAttribute('aria-current',v)}))};s();window.addEventListener('hashchange',s);window.addEventListener('popstate',s);new MutationObserver(s).observe(document.documentElement,{attributes:true,attributeFilter:['lang']})})();
